import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes3')
from h import *
X=[]
def G(g,l): return [(g,x) for x in l]
X.append(r(9969020,"Hummus de pimiento rojo asado sin aceite","Un hummus de pimiento rojo asado ahumado y delicioso, sedoso y suave, sin aceite y sin tahini.","6 porciones (rinde aprox. 2 tazas)","1 porción",
["1 frasco de 12 onzas de pimientos rojos asados (aprox. 2 pimientos)","1.5 tazas de garbanzos cocidos o enlatados (aprox. 1 lata de 15 oz)","2 cucharadas de jugo de limón","1 a 2 dientes de ajo pelados","½ cucharadita de sal marina o al gusto","½ cucharadita de pimentón ahumado","¼ de cucharadita de pimienta de cayena","2 a 4 cucharadas de agua para aligerar"],
["Agregue todos los ingredientes a la licuadora, comenzando con 2 cucharadas de agua. Licue hasta obtener una mezcla suave.","Pruebe y ajuste la sal si es necesario y agregue otras 2 cucharadas de agua si prefiere una consistencia más líquida.","Sirva con verduras, pan pita, totopos o cualquier otra cosa que desee."],
["Use pimientos rojos asados envasados en agua (no en aceite) para mantener bajo el contenido de grasa. O ase sus propios pimientos si lo prefiere. Si ase sus propios pimientos, retire la mayor parte de la piel carbonizada/negra, pero no se preocupe por quitar cada pedacito, ya que esos trocitos agregarán una profundidad de sabor más intensa. Guarde las sobras en un recipiente sellado en el refrigerador hasta por 5 días. O congele en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9969110,"Rollitos veganos de calabacita","La calabacita tierna, el queso ricotta vegano, la salsa marinara y el parmesano vegano forman la comida reconfortante saludable por excelencia.","6 porciones","1 porción",
["2 libras de calabacita (aprox. 3 calabacitas medianas)",
("Para el queso ricotta vegano","1.5 tazas de nueces de la India crudas"),("Para el queso ricotta vegano","¼ de taza de levadura nutricional"),("Para el queso ricotta vegano","2 cucharadas de vinagre de manzana"),("Para el queso ricotta vegano","½ cucharadita de ajo en polvo"),("Para el queso ricotta vegano","½ cucharadita de sal marina"),("Para el queso ricotta vegano","½ taza de agua"),
("Para la salsa","1.5 tazas de salsa de tomate o puré de tomate"),("Para la salsa","2 a 3 cucharadas de albahaca fresca finamente picada"),("Para la salsa","½ cucharadita de orégano seco"),
("Decoración opcional","½ taza de parmesano vegano")],
["Precaliente el horno a 375 grados F (190 grados C). Luego tome una bandeja grande para hornear y fórrela con toallas de papel o un paño de cocina limpio.","Corte la calabacita a lo largo en rebanadas de 1/8 de pulgada de grosor. Acomode las rebanadas en una sola capa sobre la bandeja y espolvoree generosamente con sal. Reserve y deje reposar 15 minutos. (La sal ablandará la calabacita, soltará el exceso de humedad y la hará flexible para enrollar.)","Mientras tanto, prepare su queso agregando todos los ingredientes de la ricotta vegana al procesador de alimentos. Procese hasta obtener una mezcla suave y reserve.","Ahora, combine los ingredientes de la salsa en un tazón pequeño y reserve.","Para este momento, su calabacita debería estar lista para enrollar. Seque las rebanadas con toques para quitar el exceso de humedad. Luego extienda 1 taza de la salsa de tomate preparada en el fondo de un molde para hornear o una sartén de hierro fundido de 10 pulgadas. (O en otro recipiente apto para horno.)","Agregue aprox. una cucharadita de la mezcla de ricotta a una rebanada de calabacita y luego, comenzando por la parte de abajo, enróllela. Colóquela en el molde, de pie, sobre la capa de salsa de tomate. Repita con las rebanadas restantes. Luego cubra los rollitos de calabacita con la salsa restante y espolvoree con parmesano vegano, si lo usa.","Cubra con una tapa, o con papel pergamino seguido de papel aluminio, y hornee de 20 a 25 minutos, hasta que la calabacita esté tierna, pero no demasiado cocida. Saque del horno y sirva."],
["Si no tiene una licuadora de alta velocidad, remoje las nueces de la India en agua hirviendo durante 30 minutos y luego escúrralas antes de procesar. No omita salar la calabacita. Ese paso es lo que hace que la calabacita quede lo bastante suave para enrollarse mientras suelta el exceso de humedad. Las sobras se conservan refrigeradas de 2 a 3 días o congeladas hasta por 3 meses."],[]))
X.append(r(9970596,"Frijoles refritos sin aceite","Una receta súper sencilla de frijoles refritos DELICIOSOS, sin aceite, que puede preparar en solo 25 minutos.","8 porciones","1 porción",
["4 cucharadas de caldo de verduras","½ taza de cebolla blanca en cubos","2 a 3 dientes de ajo picados","1 cucharadita de chile en polvo","1 cucharadita de pimentón ahumado","½ cucharadita de comino","3 tazas de frijoles pintos cocidos o enlatados","¾ de taza de caldo de verduras","2 cucharadas de cilantro fresco","1 a 2 cucharadas de jugo de limón verde"],
["Agregue las cuatro cucharadas de caldo a una sartén grande con la cebolla en cubos. Saltee hasta que estén suaves, aprox. de 4 a 5 minutos, agregando más caldo o agua, si es necesario para evitar que se pegue.","Luego agregue el ajo y las especias, mezcle bien y cocine otros 30 segundos.","Después, agregue los frijoles pintos y los 3/4 de taza restantes de caldo a la sartén y cocine a fuego lento durante 5 minutos, hasta que el líquido se reduzca en su mayor parte. Apague el fuego y use un machacador de papas para machacar la mayoría de los frijoles.","Ahora agregue el cilantro y el jugo de limón, y mezcle bien. Pruebe la sal y agregue si es necesario. (Esto dependerá de lo salado que sea su caldo.)","Use en platillos como burritos, tacos, fajitas y más."],
["Use un caldo de buena calidad, sabroso/salado, para obtener el mejor sabor. Yo uso esta mezcla casera de concentrado de caldo. Si usa un caldo bajo en sodio, puede que necesite agregar un poco de sal al producto final. Pruebe y ajuste según sea necesario. Para frijoles refritos más suaves, machaque por más tiempo o use un procesador de alimentos o una licuadora si no quiere nada de textura. Los frijoles refritos sobrantes se conservan en un recipiente hermético en el refrigerador de 3 a 4 días o congelados en un recipiente apto para congelador hasta por 6 meses."],[]))
X.append(r(9973119,"Tater tots de calabacita horneados","Los tater tots de calabacita horneados son una opción más saludable para las comidas familiares. Súper sabrosos, con el exterior crujiente y el interior suave y esponjoso.","4 porciones (aprox. 24 a 30 tater tots)","1 porción",
["1 libra de papas amarillas (5 a 6 papas pequeñas) peladas","300 gramos de calabacita (aprox. 1 mediana o 2 pequeñas)","1 cucharadita de pimentón","1 cucharadita de ajo en polvo","½ cucharadita de sal marina"],
["Coloque las papas en una olla mediana y cúbralas con agua. Lleve a hervor y cocine de 8 a 10 minutos, hasta que un tenedor pueda atravesar los bordes. No las cocine de más o quedarán demasiado blandas para rallarlas. Escurra y enjuague de inmediato con agua fría, luego seque con toques. Reserve.","Mientras tanto, ralle la calabacita sobre toallas de papel o un paño de cocina limpio. Luego exprima la mayor cantidad de agua que pueda sobre el fregadero. Pase la calabacita rallada a un tazón grande para mezclar y luego ralle las papas en el mismo tazón y agregue el condimento. Mezcle bien.","Precaliente el horno a 425° F / 218° C y forre una bandeja grande para hornear con papel pergamino.","Use las manos para dar a la mezcla forma de cilindros, usando aprox. 1 cucharada de la mezcla para cada uno. Mantenga los tater tots pequeños para una textura más crujiente. Coloque cada uno en la bandeja preparada y repita con el resto de la mezcla. Obtendrá de 24 a 30 tater tots.","Hornee de 20 a 25 minutos, luego voltéelos con cuidado y hornee otros 10 minutos, hasta alcanzar la crujiencia deseada."],
["No cocine de más las papas o quedarán demasiado blandas y difíciles de rallar. Exprima la mayor cantidad de humedad posible de la calabacita rallada antes de mezclarla con las papas. No quiere demasiado exceso de humedad. Mantenga los tater tots pequeños para una textura más crujiente. Como esta receta no lleva aceite, tenga cuidado al voltearlos. Si los tater tots se sienten un poco pegados o difíciles de voltear, hornéelos unos minutos extra para que se firmen más e inténtelo de nuevo. Saben mejor recién hechos, pero puede guardar las sobras en el refrigerador de 3 a 4 días. Recaliente en el horno, la freidora de aire o el horno tostador para devolverlos a un estado crujiente."],[]))
X.append(r(9975367,"Wraps veganos de ensalada de col asiática con arroz de coliflor","Para wraps frescos INCREÍBLES con delicioso sabor a cacahuate, no busque más que estos nutritivos wraps veganos de ensalada de col asiática. Perfectos para alimentar a mucha gente.","8 wraps","1 porción",
["1 cucharadita de aceite de coco (*vea la opción sin aceite en las notas abajo)","1 coliflor pequeña o media coliflor grande (rinde 4 tazas de coliflor en forma de arroz)","½ cucharadita de sal marina","4 tazas de mezcla para ensalada de col (yo uso una mezcla de betabel, brócoli y zanahoria, ¡o prepare la suya!)","¼ de taza de cilantro fresco picado","8 tortillas para wrap de 10 pulgadas (sin gluten si es necesario)",
("Ingredientes del aderezo","2 cucharadas de crema de cacahuate lisa"),("Ingredientes del aderezo","3 cucharadas de tamari o salsa de soya"),("Ingredientes del aderezo","3 cucharadas de vinagre de arroz"),("Ingredientes del aderezo","2 cucharadas de jarabe de arce"),("Ingredientes del aderezo","1 cucharada de jugo de limón verde (aprox. medio limón)"),("Ingredientes del aderezo","½ cucharadita de ajo en polvo"),("Ingredientes del aderezo","½ cucharadita de sriracha (opcional)")],
["Con un procesador de alimentos o un procesador de verduras, triture la coliflor hasta que tenga la consistencia del arroz. Si usa un procesador de alimentos, hágalo en tandas más pequeñas para no procesar de más la coliflor. No quiere que quede hecha puré.","Caliente el aceite de coco en una sartén grande a fuego medio-alto y espere hasta que el aceite esté caliente. Luego agregue el arroz de coliflor y espolvoree con sal. Cocine, revolviendo ocasionalmente, durante unos 10 minutos, o hasta que esté ligeramente dorado. Reserve.","Mientras tanto, agregue todos los ingredientes del aderezo a un tazón pequeño y bata para integrar. Reserve.","Coloque la ensalada de col y el cilantro en un tazón grande y luego vierta el aderezo encima y mezcle bien.","Divida el arroz de coliflor y la ensalada de col aderezada entre sus 8 wraps. Agregará aprox. 2 cucharadas de arroz de coliflor y 3 cucharadas de ensalada de col a cada wrap. Doble primero los lados de la tortilla y luego enrolle desde la parte de abajo para que nada se salga por los bordes. No los rellene demasiado o serán difíciles de enrollar.","Opcional pero recomendado: Use una máquina para paninis o una parrilla para asar ligeramente los wraps, con el lado doblado hacia abajo, durante unos 2 minutos. Esto ayudará a mantener los wraps unidos y les dará hermosas marcas de parrilla.","Sirva los wraps cortados por la mitad o enteros. ¡Disfrute!"],
["No rellene demasiado sus wraps veganos. No solo serán difíciles de doblar, sino que también serán mucho más desordenados de comer. Para ahorrar tiempo, puede comprar ensalada de col ya preparada (elija su mezcla de verduras favorita). También puede comprar arroz de coliflor ya preparado. Necesitará 4 tazas de cada uno. Si tiene tiempo para hacerlo, recomiendo mucho asar los wraps veganos a la parrilla. Ayuda a mantenerlos unidos, sellando los bordes para formar una bolsita bonita y ordenada. Para que no lleve aceite: Saltee el arroz de coliflor en agua o caldo en lugar del aceite de coco."],[]))
X.append(r(9980070,"Hummus de crema de cacahuate","Este hummus de crema de cacahuate está lleno de proteína y deliciosos sabores de inspiración tailandesa. Pruébelo con su próxima charola de verduras y galletas saladas.","2 tazas","1 cucharada",
["1 lata de 15 oz de garbanzos, escurridos y enjuagados","¼ de taza de crema de cacahuate lisa","½ limón verde recién exprimido","3 cucharadas de tamari o salsa de soya (si no evita el gluten)","1 cucharada de jarabe de arce","¼ de cucharadita de ajo en polvo","¼ de cucharadita de jengibre molido","¼ de cucharadita de pimienta de cayena"],
["Agregue todos los ingredientes a un procesador de alimentos y procese hasta obtener una mezcla suave e integrada.","Opcional: Sirva espolvoreado con un poco más de pimienta de cayena o pimentón si lo desea."],[],[]))
X.append(r(9983478,"Avena de calabaza preparada de un día para otro","Una receta deliciosa y nutritiva de avena de calabaza preparada de un día para otro, perfecta para las mañanas ocupadas.","1 porción","1 porción",
["1/2 taza de puré de calabaza (NO relleno para pay de calabaza)","1/2 taza de avena en hojuelas","2/3 de taza de leche sin lácteos y sin azúcar (me gusta la de soya, avena o almendra)","2 cucharadas de semillas de chía","2 cucharaditas de jarabe de arce","1 cucharadita de especias para pay de calabaza","chispas de chocolate, mitades de nuez pecana, fruta fresca"],
["Agregue todo a un tazón pequeño y revuelva para integrar.","Refrigere durante la noche, o al menos 4 horas. Luego agregue sus coberturas favoritas y disfrute."],[],[]))
X.append(r(9984117,"Cómo hacer jugo de fresa","Una receta de jugo de fresa fresco y delicioso con SOLO dos ingredientes. Es naturalmente dulce con un sutil toque de sabor a limón, refrescante y sabroso.","2 (rinde aprox. 10 onzas o 1 + 1/4 de taza)","1 porción",
["1 libra de fresas frescas","⅛ de limón"],
["Lave bien las fresas y quíteles los tallos.","Extraiga el jugo de las fresas y el limón, revuelva rápidamente y disfrute de inmediato."],
["Haga la cantidad de jugo que planea consumir, no más. El jugo recién hecho sin conservadores no se conserva mucho tiempo y, para obtener los máximos beneficios para la salud, debe disfrutarse de inmediato.","Para acelerar el tiempo de preparación del jugo, puede lavar y secar sus frutas la noche anterior y refrigerarlas en un recipiente sellado. Luego, por la mañana, su fruta estará lista para pasar por el extractor de jugos."],[]))
X.append(r(9984982,"Magdalenas de harina de almendra y zarzamoras","Magdalenas de harina de almendra y zarzamoras súper húmedas y sabrosas, con un delicioso sabor y una miga delicada.","12 magdalenas","1 porción",
G("Ingredientes secos",["250 gramos de harina de almendra blanqueada (aprox. 2.5 tazas)","½ taza de avena en hojuelas (no avena instantánea)","1.5 cucharaditas de polvo para hornear","1 cucharadita de canela"])+
G("Ingredientes húmedos",["½ taza de puré de manzana sin azúcar","½ taza de crema de nuez de la India","⅓ de taza de jarabe de arce","⅓ de taza de leche de almendra o la leche vegetal de su elección","1 cucharadita de extracto puro de vainilla","1 taza de zarzamoras frescas"]),
["Precaliente el horno a 350 grados F y tome un molde antiadherente para magdalenas con capacidad para 12 magdalenas. Engrase si es necesario.","Agregue los ingredientes secos a un tazón grande para mezclar y bata juntos. Reserve. Luego agregue los ingredientes húmedos a un tazón mediano y mezcle bien para integrar de manera uniforme la crema de nuez de la India.","Vierta la mezcla húmeda en el tazón de ingredientes secos y mezcle hasta integrar. Ahora incorpore suavemente con movimientos envolventes las zarzamoras. Tenga cuidado de no romperlas.","Divida la masa entre los 12 moldes y hornee de 22 a 24 minutos, hasta que un palillo salga casi limpio y los bordes de las magdalenas se vean dorados.","Saque del horno y deje reposar al menos 10 minutos para que se asienten por completo, antes de sacar las magdalenas del molde."],
["Para mayor exactitud, es mejor pesar la harina. Pero si no tiene una báscula de cocina, use 2.5 tazas, y ponga la harina con una cuchara y nivélela en la taza medidora. La harina de almendra blanqueada funciona mejor, así que no la sustituya por harina gruesa de almendra ni por harina sin blanquear. Asegúrese de que su polvo para hornear esté fresco y todavía activo. El polvo para hornear que lleva abierto en la despensa 6 meses o más empezará a perder su efectividad. Use zarzamoras frescas en lugar de congeladas. Las zarzamoras congeladas pueden soltar color en la masa volviéndola morada y agregan líquido extra. Sea delicado al incorporar las zarzamoras para evitar que se rompan en la masa. Dé a sus magdalenas suficiente tiempo para enfriarse en el molde antes de pasarlas. Los postres de harina de almendra pueden ser más suaves y delicados, así que es más fácil sacarlos una vez que se han enfriado un poco. Las sobras se conservan a temperatura ambiente de 2 a 3 días, refrigeradas de 5 a 6 días, o congeladas hasta por 3 meses."],[]))
X.append(r(9985547,"Bolitas energéticas de avena","Dé energía a su día con estas bolitas energéticas de avena sin hornear. Son suaves, masticables y están llenas de ingredientes nutritivos.","15 bolitas","1 porción",
["1 taza de avena en hojuelas (sin gluten, si lo prefiere)","⅓ de taza de crema de almendra cremosa","¼ de taza de jarabe de arce","1 cucharadita de extracto puro de vainilla","½ cucharadita de canela"],
["Forre una bandeja para hornear con papel pergamino y reserve.","Agregue todo a un tazón grande para mezclar y revuelva hasta integrar y que la avena quede cubierta de manera uniforme.","Use un cucharón pequeño para galletas para porcionar y formar la mezcla en bolitas del tamaño de un bocado, colocándolas en la bandeja forrada con pergamino.","Refrigere las bolitas energéticas durante 1 hora (o más) para que se firmen antes de disfrutarlas."],
["Use las manos ligeramente húmedas para dar forma a las bolitas y evitar que se peguen. La masa será pegajosa, lo cual es normal.","Las bolitas formadas serán suaves, así que refrigérelas por al menos 1 hora antes de disfrutarlas para ayudar a que se endurezcan y se asienten."],[]))
X.append(r(9986100,"Pay vegano de crema de cacahuate sin hornear","Un pay vegano de crema de cacahuate más saludable que lo dejará sorprendido. Es rico y cremoso, ligeramente dulce y absolutamente delicioso.","8 porciones","1 porción",
G("Para la base",["1 taza de dátiles sin hueso","½ taza de agua caliente + 1 a 2 cucharadas si es necesario","1.5 tazas de avena en hojuelas (no avena instantánea)"])+
G("Para el relleno",["454 gramos de tofu semifirme/firme, escurrido y secado con toques (use tofu sin transgénicos si es posible)","⅔ de taza de crema de cacahuate natural","⅔ de taza de jarabe de arce","2 cucharadas de cacao en polvo crudo sin azúcar","½ cucharadita de canela (opcional)","½ cucharadita de jengibre molido (opcional)","¼ de cucharadita de sal marina (opcional)"]),
G("Para la base",["Agregue los dátiles sin hueso y media taza de agua caliente al procesador de alimentos y procese hasta obtener una mezcla suave, raspando los lados según sea necesario. Agregue otra cucharada o dos de agua caliente, si es necesario, para obtener una consistencia suave.","Agregue la avena en hojuelas a la mezcla de pasta de dátiles y procese hasta integrar, y que la mayor parte de la avena se haya desmenuzado, pero no es necesario que quede suave.","Pase la mezcla a su molde antiadherente para tarta y use los dedos húmedos para presionar de manera uniforme sobre la base y los lados. Reserve."])+
G("Para el relleno",["Agregue todos los ingredientes del relleno al procesador de alimentos y procese hasta que quede completamente suave, raspando los lados según sea necesario.","Luego vierta el relleno sobre la base preparada y use una espátula de silicona para extenderlo de manera uniforme y alisar la parte superior.","Congele durante 2 horas y luego decore con chispas de chocolate y un chorrito de crema de cacahuate extra antes de servir, si lo desea."]),
["Use un molde antiadherente para tarta con fondo desmontable. Esto hará que sacar el pay sea MUCHO más sencillo. (Este pay está fotografiado en un molde antiadherente para tarta de 11 pulgadas, pero también funcionará con uno de 9 o 10 pulgadas.) Use las manos húmedas para presionar la base en el molde para tarta, para evitar que se pegue. Si le gusta lo dulce, pruebe el relleno una vez procesado (antes de verterlo sobre la base del pay) y agregue otro ¼ de taza de jarabe de arce si es necesario. Almacenamiento: Si no va a consumir todo el pay, devuelva las sobras al congelador de inmediato. No deje que se descongele por completo y luego lo vuelva a congelar, ya que altera el sabor y la textura.","Si no le importa que el pay quede muy suave, también puede guardar las sobras en el refrigerador de 3 a 4 días."],[]))
X.append(r(9991273,"Papas y cebollas en freidora de aire","Las papas y cebollas en freidora de aire, doradas, crujientes y deliciosas, son una guarnición ideal que puede tener lista en solo 30 minutos o menos.","2 porciones","1 porción",
["1 libra de papas russet (aprox. 2 papas grandes), rebanadas finamente","1 cebolla amarilla grande rebanada","1.5 cucharadas de caldo de verduras","1 cucharadita de ajo en polvo","1 cucharadita de orégano seco","sal y pimienta al gusto"],
["Lave bien y rebane las papas muy delgadas, con una mandolina u otra herramienta para rebanar, aprox. 1/8\" de grosor. Rebane las cebollas más gruesas, ya que se cocinan más rápido.","Mezcle las papas rebanadas, las cebollas, el caldo y el condimento en un tazón grande hasta cubrirlas de manera uniforme. Luego pase todo a la canasta de la freidora.","Cocine las papas y las cebollas en la freidora de aire a 400° F/204° C durante aprox. 20 minutos, y revuelva o agite la canasta cada 5 minutos, hasta alcanzar el punto de cocción deseado. Sirva caliente con perejil o albahaca recién picados si lo desea."],
["Corte las papas lo más uniformes posible para una cocción y crujiencia uniformes.","El modelo de la freidora de aire y el grosor de las papas determinarán el tiempo de cocción, así que vigile con cuidado hacia el final de la cocción.","Para papas más crujientes, puede usar un aceite de buena calidad, como aceite de aguacate, en lugar de caldo, pero esto aumentará las calorías y la grasa. (No recomiendo cocinar con aceite de oliva debido a su bajo punto de humo.)"],[]))
X.append(r(9991817,"Curry de garbanzos y champiñones con rapini","Un curry de garbanzos y champiñones en una sola olla, ¡lleno de sabor intenso y audaz!","6 porciones","1 porción",
["1 cucharada de aceite de aguacate (omítalo y use agua o caldo para que no lleve aceite)","1 cebolla morada finamente picada","3 dientes de ajo pelados y finamente picados o machacados","1 cucharada de jengibre fresco finamente picado o rallado","1 libra de champiñones rebanados","450 gramos de rapini o brócoli baby (aprox. 1 manojo), sin los extremos y cortado por la mitad o en tercios","1 cucharadita de cúrcuma en polvo","1 cucharadita de curry en polvo","½ cucharadita de pimienta de cayena","2 tazas de salsa de tomate o puré de tomate","400 ml de leche de coco sin azúcar Thai Kitchen","1 lata de 19 onzas de garbanzos, escurridos y enjuagados","¾ de cucharadita de sal marina",("Opcional","Sirva con arroz blanco o integral o pan naan"),("Opcional","Decore con gajos de limón verde, cilantro fresco y chiles rojos.")],
["Agregue el aceite (si lo usa), la cebolla, el ajo y el jengibre a una sartén honda. Saltee durante 5 minutos, hasta que se ablanden, revolviendo con frecuencia.","Luego agregue los champiñones y el rapini a la sartén y coloque la tapa encima para marchitar el rapini y reducir los champiñones, unos 5 minutos. Revuelva ocasionalmente.","Agregue todos los demás ingredientes (excepto las decoraciones opcionales) a la olla y mezcle bien. Cocine a fuego lento a temperatura media durante unos 20 a 25 minutos. Luego pruebe, agregue más sal o pimienta si es necesario, y sirva."],
["Agregue más verduras a este curry de champiñones y garbanzos si lo desea. Puede agregar chícharos, ejotes, brócoli, coliflor o cualquier verdura que le guste.","Asegúrese de usar leche de coco ENLATADA, no la que viene en cartón.","¡Haga su curry tan picante como quiera! Ajuste la pimienta de cayena a su gusto. Si es la primera vez que prepara comida india, use menos y vaya aumentando a partir de ahí, ya que este platillo tiene muchos otros sabores y condimentos.","Para más profundidad de sabor, agregue ½ cucharadita de semillas de comino en el paso de saltear y ½ cucharadita de garam masala antes de cocinar a fuego lento.","Para menos grasa: Use leche de coco light en lugar de regular. Pero tenga en cuenta que tendrá menos sabor a coco y el curry será menos cremoso","Para que no lleve coco: Use crema de nuez de la India, tofu sedoso o yogur sin lácteos con resultados similares.","Para que no lleve aceite, use caldo de verduras o agua para saltear, en lugar de aceite.","Las sobras se conservan refrigeradas de 3 a 4 días, solo recaliente y disfrute."],[]))
X.append(r(9992614,"Champiñones saludables en freidora de aire [sin aceite]","Los champiñones en freidora de aire son la guarnición o cobertura de ensalada perfecta. ¡Llenos de sabor umami, con solo 4 ingredientes y listos en unos 10 minutos!","2 porciones","1 porción",
["8 oz de champiñones cremini limpios y secos, partidos por la mitad","1 cucharada de tamari o salsa de soya baja en sodio (si no evita el gluten)","1 cucharada de jugo de limón (aprox. medio limón mediano)","½ cucharadita de ajo en polvo","⅛ de cucharadita de pimienta negra (opcional)"],
["Parta por la mitad los champiñones limpios y secos (o en cuartos si son grandes) y colóquelos en un tazón para mezclar. Agregue todos los demás ingredientes al tazón y mezcle bien.","Colóquelos en la canasta de la freidora de aire y programe a 390 grados F, cocinando de 8 a 10 minutos. Agite la canasta o mezcle los champiñones cada pocos minutos. ¡Disfrute!"],
["Agite la canasta o revuelva los champiñones cada pocos minutos durante la cocción para evitar que se peguen y dorarlos de manera uniforme. No corte los champiñones demasiado pequeños. Como se reducirán bastante durante la cocción, simplemente córtelos por la mitad. Si sus champiñones son muy grandes, puede cortarlos en cuartos. Trate de no sobrecargar la canasta con los champiñones. Como sueltan bastante agua mientras se cocinan, no quiere que se cuezan al vapor. Así que colóquelos en una sola capa."],[]))
X.append(r(9992749,"Galletas saladas de frijol blanco con proteína","¡Galletas saladas de frijol blanco con proteína, perfectamente crujientes y satisfactorias!","6 porciones","1 porción",
G("Ingredientes húmedos",["1 lata de 19 onzas de frijoles blancos (alubias), escurridos y enjuagados (aprox. 2 tazas)","½ taza de leche de soya o la leche vegetal de su elección"])+
G("Ingredientes secos",["¼ de cucharadita de ajo en polvo","¼ de cucharadita de cebolla en polvo","¾ de cucharadita de sal marina o al gusto","110 gramos de harina de avena (aprox. 1+¼ de taza)","120 gramos de harina de garbanzo (aprox. 1+¼ de taza)","2 cucharadas de almidón de tapioca o fécula de maíz"])+
G("Opcional",["aceite de oliva","romero seco triturado"]),
["Precaliente el horno a 350° F/176° C y forre dos bandejas grandes para hornear con papel pergamino.","Licue los frijoles y la leche hasta obtener una mezcla suave y luego pase la mezcla a un tazón grande.","Agregue todos los ingredientes secos y mezcle hasta obtener una bola de masa. Será firme, pero más suave y pegajosa que la masa de pizza.","Divida la masa aproximadamente por la mitad y coloque cada mitad en las bandejas preparadas, o trabaje sobre la encimera si le resulta más fácil. (Asegúrese de que la masa esté sobre papel pergamino, y no directamente sobre la bandeja o la encimera, para evitar que se pegue.)","Coloque otra hoja de papel pergamino sobre la masa y use un rodillo para aplanar y estirar la masa de la manera más uniforme y delgada posible sin romperla. Luego retire el papel pergamino de encima de la masa y alise los bordes ásperos o redondeados para enderezarlos con una espátula de silicona o con los dedos. (Esto ayudará a obtener galletas saladas uniformes, pero no es del todo necesario.)","Corte la masa en un patrón de cuadrícula con un cortador de galletas o de pizza. Separe ligeramente cada fila y columna empujando los bordes con el cortador. Esto ayudará a que los bordes queden crujientes. Luego use un tenedor para picar la masa por todas partes.","Opcional: Barnice la masa con aceite de oliva y espolvoree con romero y más sal si lo desea.","Hornee en el horno precalentado de 30 a 35 minutos, hasta que los bordes de las galletas estén dorados. Saque del horno, deje enfriar a temperatura ambiente y sirva con un dip o solas."],
["Si no tiene harina de avena o harina de garbanzo a la mano, puede hacerlas moliendo avena y/o garbanzos en una licuadora de alta velocidad. (Yo uso mi Vitamix.)","La masa será firme, pero más suave y pegajosa que la masa de pizza. Esto es normal.","Use DOS hojas de papel pergamino (1 debajo y 1 encima de la masa) al estirarla, para evitar que se pegue al rodillo.","Separe las filas de galletas saladas con proteína Y pique la masa con","Si le sobran, puede guardarlas a temperatura ambiente en un recipiente sellado hasta por 5 días. Asegúrese de que estén completamente frías antes de guardarlas."],[]))
X.append(r(9996156,"Bolitas energéticas de moca","Estas bolitas energéticas de moca están llenas de sabor a café y chocolate. Además, están hechas con ingredientes nutritivos.","15 bolitas","1 porción",
["1 taza de nueces pecanas","½ taza de dátiles sin hueso, bien compactados","2 cucharadas de cacao en polvo crudo sin azúcar","2 cucharadas de jarabe de arce","1 cucharada de café instantáneo"],
["Forre una bandeja con papel pergamino y reserve. Luego, agregue todos los ingredientes al tazón del procesador de alimentos. Pulse hasta que estén bien integrados sin hacer puré completamente la mezcla.","Use un cucharón pequeño para galletas o una cuchara para tomar la mezcla y formar bolitas. Coloque cada bolita en la bandeja forrada.","Puede disfrutarlas de inmediato, o refrigerar durante 1 hora o más para que se enfríen."],
["No licue de más la mezcla, ya que estos bocadillos saben mejor con un poco de textura.","La masa es un poco pegajosa, así que use las manos húmedas para formar las bolitas y evitar que se pegue a sus manos.","Guarde sus bolitas energéticas de moca en el refrigerador hasta por 5 días o manténgalas congeladas hasta por 3 meses."],[]))
save(9,X)
